// Hostinger on the business's own API token: every operation of Hostinger's public API (VPS, web hosting and
// WordPress, domains and DNS, email, Reach email marketing, ecommerce stores, Horizons sites, billing).
// actions.json is generated by `bun scripts/openapi-actions.ts hostinger`; COVERAGE.md says what's left out.
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

const api: Api = {
  name: "Hostinger",
  base: "https://developers.hostinger.com",
  tokenHelp: "hPanel → Profile → API",
};

export const hostinger: OwnApp = {
  app: "hostinger",
  name: "Hostinger",
  logo: "/logos/hostinger.svg",
  keyField: {
    label: "API token",
    help: "In hPanel: Profile → API → Generate token (hpanel.hostinger.com/profile/api). Pick an expiry, or none.",
    placeholder: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
  },
  // every account has subscriptions to list, whatever it bought
  async check(key) {
    await call(api, key, { method: "GET", path: "/api/billing/v1/subscriptions", query: [], headers: [] }, {});
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
